from rdkit import Chem
import numpy as np
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
m=Chem.MolFromMolFile('ligand.mol',removeHs=False)
x=np.load('coords.npy')
fig=plt.figure(figsize=(11,7))
for panel,axes in enumerate([(0,1),(0,2)]):
 ax=fig.add_subplot(1,2,panel+1);a,b=axes
 for bond in m.GetBonds():
  i,j=bond.GetBeginAtomIdx(),bond.GetEndAtomIdx(); ax.plot(x[[i,j],a],x[[i,j],b],color='gray',lw=1.1)
 for i,j in [(61,2),(61,19),(61,29),(61,62),(61,63),(62,63),(62,64),(63,65)]:ax.plot(x[[i,j],a],x[[i,j],b],'k-',lw=1.3)
 symbols=[at.GetSymbol() for at in m.GetAtoms()]+['Ru','C','C','H','H'];colors={'C':'gray','N':'blue','Ru':'purple','H':'white'}
 for i,(sym,pt) in enumerate(zip(symbols,x)):
  ax.scatter(pt[a],pt[b],s=80 if sym!='H' else 25,c=colors[sym],edgecolors='k',zorder=3)
  if sym!='H':ax.text(pt[a]+.05,pt[b]+.05,str(i),fontsize=7)
 ax.set_aspect('equal');ax.set_xlabel('XYZ'[a]);ax.set_ylabel('XYZ'[b])
fig.tight_layout();fig.savefig('check.png',dpi=150)
